#pragma once

#include "dsp/noise/NoiseSample.h"

#include <memory>

namespace fcm::dsp
{

// The noises that ship with the plugin (docs/specs/noise-oscillator.md §1): White, Pink, Brown,
// Crackle, Metal, Digital (2 seconds each, meant to loop), then Air Burst and Thump (150 ms
// one-shots). Generated by code, so they are original and free to redistribute. The list is
// append-only: the saved value of the Noise Type parameter is the index. Nothing here runs on the
// audio thread.
class FactoryNoises
{
  public:
    static constexpr double kSampleRate = 48000.0;

    static int count() noexcept;
    static const char* name(int index) noexcept; // empty when out of range

    // Out-of-range indices give the first noise. Deterministic, peak-normalised to 1.
    static std::unique_ptr<const NoiseSample> build(int index);
};

} // namespace fcm::dsp
